import type { HandwritingState } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge';

export const handwritingVerificationBadge: Record<HandwritingState, { variant: BadgeVariants; label: string }> = {
  good: { variant: 'success', label: 'Verified' },
  fraud: { variant: 'destructive', label: 'Fraud' },
  suspicious: { variant: 'warning', label: 'Suspicious' },
  not_fraud: { variant: 'default', label: 'NOT Fraud' },
  na: { variant: 'default', label: 'N/A' }, //TODO check for another variant
};

const defaultHandwritingVerificationBadge: { variant: BadgeVariants; label: string } = {
  variant: 'default',
  label: '',
};

export function getHandwritingVerificationBadge(state: HandwritingState): { variant: BadgeVariants; label: string } {
  return (
    handwritingVerificationBadge[state] ?? {
      ...defaultHandwritingVerificationBadge,
      label: snakeCaseToCapitalizedCase(state),
    }
  );
}
