<template>
  <Card
    :class="
      cn('flex flex-wrap items-center justify-between px-4 py-2 w-full bg-accent border-input gap-2', {
        'ring-2 ring-blue-500': highlightedSignatureId === item.id,
        'cursor-pointer': highlightedSignatureId !== undefined,
      })
    "
  >
    <div class="flex flex-col">
      <p class="text-lg font-semibold flex gap-1 flex-wrap">
        <template v-if="item.signatory.first_name || item.signatory.last_name">
          <span class="break-all">{{ item.signatory.first_name }}</span>
          <span class="break-all">{{ item.signatory.last_name }}</span>
        </template>
        <span v-else>-</span>
      </p>
      <span class="text-sm leading-6 text-accent-foreground">
        {{ formatDateTzToFormat(item.created_at, 'MM/dd/yyyy hh:mm aaa', timezone) }}
      </span>
    </div>
    <div v-if="isValidSignatureShortInfo(item)" class="flex flex-wrap gap-2 items-center">
      <ValidSignatureStatuses
        :collected="item.is_collected"
        :handwriting="item.handwriting_state"
        :voice-verification="item.voice_verification_result"
      />
    </div>
    <div
      v-if="!isValidSignatureShortInfo(item)"
      :class="cn('flex flex-col', isSubmittedSignatureDetails(item) ? 'flex-row gap-2 items-center' : 'sm:items-end')"
    >
      <Badge
        v-if="isSubmittedSignatureShortInfo(item) || isSubmittedSignatureDetails(item)"
        class="col-span-2 justify-self-center text-nowrap"
        :variant="getSubmittedSignaturesBadge(item.status).variant"
        >{{ getSubmittedSignaturesBadge(item.status).label }}
      </Badge>
      <span
        v-if="!isSubmittedSignatureDetails(item) && isSubmittedSignatureShortInfo(item)"
        class="text-sm leading-6 text-muted-foreground"
        >source: {{ getSubmittedSignatureSourceLabel(item.source) }}</span
      >
      <Button
        v-if="isSubmittedSignatureDetails(item)"
        variant="outline"
        size="icon"
        @click.stop.prevent="$emit('signature-item-click', item.id)"
      >
        <LinkIcon />
      </Button>
    </div>
  </Card>
</template>

<script setup lang="ts">
import { getSubmittedSignaturesBadge } from '~/constants/verifications/submittedSignatureStatus';
import { getSubmittedSignatureSourceLabel } from '~/constants/verifications/submittedSignatureSource';
import { cn } from '@/lib/utils';
import type { ValidSignatureShortInfo, SubmittedSignatureShortInfo, SubmittedSignatureDetails } from '~/client';
import { isSubmittedSignatureDetails, isSubmittedSignatureShortInfo } from '~/utils/typeCheckers/signatures';
import { LinkIcon } from 'lucide-vue-next';

interface Props {
  item: ValidSignatureShortInfo | SubmittedSignatureShortInfo | SubmittedSignatureDetails;
  highlightedSignatureId?: string | null;
}

defineProps<Props>();

interface Emits {
  (e: 'signature-item-click', value: string): void;
}

defineEmits<Emits>();

const { timezone } = useUserRole();
</script>
