import type { ValidSignatureShortInfo, SubmittedSignatureShortInfo, SubmittedSignatureDetails } from '~/client';

export function isSubmittedSignatureShortInfo(item: unknown): item is SubmittedSignatureShortInfo {
  return typeof item === 'object' && item !== null && 'status' in item;
}

export function isValidSignatureShortInfo(item: unknown): item is ValidSignatureShortInfo {
  return typeof item === 'object' && item !== null && 'voice_verification_result' in item;
}

export function isSubmittedSignatureDetails(item: unknown): item is SubmittedSignatureDetails {
  return typeof item === 'object' && item !== null && 'row_index' in item;
}
