import type { VoiceVerificationResult } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge';

export const voiceVerificationBadge: Record<
  VoiceVerificationResult | 'none',
  { variant: BadgeVariants; label: string }
> = {
  valid: { variant: 'success', label: 'Verified' },
  invalid: { variant: 'destructive', label: 'Not Verified' },
  not_found: { variant: 'default', label: 'Not Found' },
  none: { variant: 'default', label: 'N/A' }, //TODO check for another variant
};

const defaultVoiceVerificationBadge: { variant: BadgeVariants; label: string } = { variant: 'default', label: '' };

export function getVoiceVerificationBadge(result: VoiceVerificationResult | null): {
  variant: BadgeVariants;
  label: string;
} {
  const key = result ?? 'none';
  return voiceVerificationBadge[key] ?? { ...defaultVoiceVerificationBadge, label: snakeCaseToCapitalizedCase(key) };
}
